using System;
using System.Linq;
using System.Collections.Generic;
using Newtonsoft.Json;
using EnusDE.Signaltechnik;

static class LineTutorialTests {
    static void Check(bool ok,string message){if(!ok)throw new Exception("FAIL: "+message);System.Console.WriteLine("PASS: "+message);}
    static bool Reject(Action action){try{action();return false;}catch(InvalidOperationException){return true;}}
    static string Id()=>Guid.NewGuid().ToString("N");
    static MarkerRecord Signal(string name,string segment,double meters,bool reverse)=>new MarkerRecord{Id=Id(),Name=name,Kind=MarkerRecord.Main,Anchor=new MarkerAnchor{Segment=segment,Meters=meters},FacingReverse=reverse};
    public static void Run() {
        Check(LineTutorial.SignalSteps(LineTrackMode.Gleiswechselbetrieb).SequenceEqual(new[]{LineSignalGroup.AArrivals,LineSignalGroup.ADepartures,LineSignalGroup.BArrivals,LineSignalGroup.BDepartures}),"GWB tutorial asks for entry A, departure A, entry B and departure B in four separate ordered steps");
        string key=new string('a',64);var library=new DeskLibrary{WorldKey=key,Desks=new List<DeskDefinition>{new DeskDefinition{Global=true,Code="MASTER",Name="Master",Panel=new PanelDocument{WorldKey=key}},new DeskDefinition{Code="HG",Name="Hemingway",Panel=new PanelDocument{WorldKey=key}},new DeskDefinition{Code="AJ",Name="Alarka Junction",Panel=new PanelDocument{WorldKey=key}}}};
        var a=library.Desks[1];var b=library.Desks[2];
        var entryA=Signal("HS-A-in","line",20,true);var exitA=Signal("HS-A-out","A",20,false);var entryB=Signal("HS-B-in","line",780,false);var exitB=Signal("HS-B-out","B",80,true);var exitA2=Signal("HS-A-out-2","AS",20,false);var signals=new[]{entryA,exitA,entryB,exitB,exitA2};
        foreach(var pair in new[]{(a,entryA,2),(a,exitA,5),(a,exitA2,7),(b,entryB,2),(b,exitB,5)})pair.Item1.Panel.Put(new PanelTile{X=pair.Item3,Y=2,Kind=PanelTileKind.Signal,Reference=pair.Item2.Id,Ports=17});
        var graph=new NetworkInput{World=key,Nodes=new List<PlanNode>{new PlanNode{Id="a"},new PlanNode{Id="wa",Point=true,Common="line",Normal="A"},new PlanNode{Id="wb",Point=true,Common="line",Normal="B"},new PlanNode{Id="b"},new PlanNode{Id="as"},new PlanNode{Id="bs"}},Edges=new List<PlanEdge>{new PlanEdge{Id="A",A="a",B="wa",Length=100},new PlanEdge{Id="line",A="wa",B="wb",Length=800},new PlanEdge{Id="B",A="wb",B="b",Length=100},new PlanEdge{Id="AS",A="as",B="wa",Length=100},new PlanEdge{Id="BS",A="wb",B="bs",Length=100}}};
        var line=LineSetupWorkflow.Create(library,a.Id);line.Mode=LineTrackMode.Gleiswechselbetrieb;
        MarkerRecord Resolve(string id)=>signals.FirstOrDefault(s=>s.Id==id);
        Check(LineTutorial.SelectionIssue(library,line,LineSignalGroup.AArrivals,Resolve)!=null,"an incomplete entry step supplies an instruction before the tutorial can advance");
        LineSignalGroups.Put(line,LineSignalGroup.AArrivals,new[]{entryA.Id});LineSignalGroups.Put(line,LineSignalGroup.ADepartures,new[]{exitA.Id});LineSignalGroups.Put(line,LineSignalGroup.BArrivals,new[]{entryB.Id});LineSignalGroups.Put(line,LineSignalGroup.BDepartures,new[]{exitB.Id});
        Check(LineTutorial.SignalSteps(line.Mode).All(g=>LineTutorial.SelectionIssue(library,line,g,Resolve)==null),"placed and assigned ordinary main signals pass tutorial role selection without pre-existing entry/exit duties");
        var wrong=line.Clone();LineSignalGroups.Put(wrong,LineSignalGroup.ADepartures,new[]{entryA.Id});
        Check(LineTutorial.SelectionIssue(library,wrong,LineSignalGroup.ADepartures,Resolve)!=null,"selecting the same inward head as entry and departure is explained at the departure step");
        wrong=line.Clone();LineSignalGroups.Put(wrong,LineSignalGroup.ADepartures,new[]{exitA.Id,entryA.Id});
        Check(LineTutorial.SelectionIssue(library,wrong,LineSignalGroup.ADepartures,Resolve)!=null,"every member of a multiple selection is checked against the opposite role");
        var multi=line.Clone();
        Check(LineTutorial.ToggleSelection(library,multi,LineSignalGroup.ADepartures,exitA2.Id,Resolve)&&LineSignalGroups.Get(multi,LineSignalGroup.ADepartures).SequenceEqual(new[]{exitA.Id,exitA2.Id})&&multi.ForwardStart==exitA.Id,"adding a second departure preserves the first signal and its reference position");
        Check(LineTutorial.SelectionIssue(library,multi,LineSignalGroup.ADepartures,Resolve)==null,"both completed departures in the owning station are accepted in one tutorial step");
        Check(LineTutorial.Selected(multi,LineSignalGroup.ADepartures,a.Panel.At(5,2))&&LineTutorial.Selected(multi,LineSignalGroup.ADepartures,a.Panel.At(7,2))&&!LineTutorial.Selected(multi,LineSignalGroup.ADepartures,a.Panel.At(2,2)),"both selected signal fields receive green state while the unselected entry does not");
        Check(LineTutorial.Selected(multi,LineSignalGroup.ADepartures,new PanelTile{Kind=PanelTileKind.Signal,Reference=entryA.Id,AlternateSignal=exitA2.Id})&&!LineTutorial.Selected(multi,LineSignalGroup.ADepartures,null),"selected alternate heads are marked and empty fields are not");
        Check(!LineTutorial.ToggleSelection(library,multi,LineSignalGroup.ADepartures,exitA2.Id,Resolve)&&LineSignalGroups.Get(multi,LineSignalGroup.ADepartures).SequenceEqual(new[]{exitA.Id})&&!LineTutorial.Selected(multi,LineSignalGroup.ADepartures,a.Panel.At(7,2)),"clicking the second signal again removes only it and its green state without duplicates");
        LineTutorial.ToggleSelection(library,multi,LineSignalGroup.ADepartures,exitA2.Id,Resolve);
        Check(!LineTutorial.ToggleSelection(library,multi,LineSignalGroup.ADepartures,exitA.Id,Resolve)&&multi.ForwardStart==exitA2.Id&&LineSignalGroups.Get(multi,LineSignalGroup.ADepartures).Count==1,"removing the first selected departure promotes the remaining reference");
        Check(!LineTutorial.ToggleSelection(library,multi,LineSignalGroup.ADepartures,exitA2.Id,_=>null)&&LineTutorial.SelectionIssue(library,multi,LineSignalGroup.ADepartures,Resolve)!=null,"a missing selected object can be deselected and the empty step cannot advance");
        Check(Reject(()=>LineTutorial.ToggleSelection(library,multi,LineSignalGroup.ADepartures,exitB.Id,Resolve))&&LineSignalGroups.Get(multi,LineSignalGroup.ADepartures).Count==0,"a signal from the wrong station cannot mutate the current selection");
        LineSignalGroups.Put(multi,LineSignalGroup.ADepartures,new[]{exitA.Id,exitA2.Id});
        var planned=exitA2.Clone();planned.Planned=true;var unsupported=exitA2.Clone();unsupported.AllowHp1=unsupported.AllowHp2=false;
        Check(LineTutorial.SelectionIssue(library,multi,LineSignalGroup.ADepartures,id=>id==exitA2.Id?planned:Resolve(id))?.Contains(exitA2.Name)==true,"an invalid secondary signal is identified by name rather than validating only the reference");
        Check(LineTutorial.SelectionIssue(library,multi,LineSignalGroup.ADepartures,id=>id==exitA2.Id?unsupported:Resolve(id))!=null,"a secondary departure without a train proceed aspect cannot pass the step");
        var entryConflict=line.Clone();LineSignalGroups.Put(entryConflict,LineSignalGroup.AArrivals,new[]{entryA.Id,exitA2.Id});LineSignalGroups.Put(entryConflict,LineSignalGroup.ADepartures,new[]{exitA.Id,exitA2.Id});
        Check(LineTutorial.SelectionIssue(library,entryConflict,LineSignalGroup.ADepartures,Resolve)!=null&&LineTutorial.SelectionIssue(library,entryConflict,LineSignalGroup.AArrivals,Resolve)!=null,"role overlap is checked against all selected heads in either editing order");
        var capped=line.Clone();LineSignalGroups.Put(capped,LineSignalGroup.ADepartures,Enumerable.Range(0,32).Select(_=>Id()));string cappedBefore=JsonConvert.SerializeObject(capped);
        Check(Reject(()=>LineTutorial.ToggleSelection(library,capped,LineSignalGroup.ADepartures,exitA2.Id,Resolve))&&JsonConvert.SerializeObject(capped)==cappedBefore,"the existing 32-signal limit is enforced before mutating the draft");
        string before=JsonConvert.SerializeObject(library);
        var forward=LineSetupSearch.Find(graph,signals,exitA,entryB);var reverse=LineSetupSearch.Find(graph,signals,exitB,entryA);
        Check(forward.Count==1&&reverse.Count==1&&library.Blocks.Count==0&&library.Automation.Signals.Count==0,"physical setup search works from signals alone, before GFM, flank design, route storage or automatic-signal setup");
        Check(JsonConvert.SerializeObject(library)==before,"setup geometry discovery changes no operating state, routes or world configuration");
        line.Forward=LineTrackGeometry.Normalize(forward[0].Routes.SelectMany(r=>r.Path));line.Reverse=LineTrackGeometry.Normalize(reverse[0].Routes.SelectMany(r=>r.Path));
        Check(line.Axis.Count==1&&line.Axis[0].Section.Segment=="line"&&line.Axis[0].Section.From==20&&line.Axis[0].Section.To==780,"opposite signal paths identify the shared free-line corridor while retaining station approaches for later detection checks");
        var alternate=LineSetupSearch.Find(graph,signals,exitA2,entryB);
        Check(alternate.Any(p=>DirectionBlockBuilder.Covers(line.Axis,new[]{new DirectionBlock{Axis=p.Routes.SelectMany(r=>r.Path).ToList()}})&&DirectionBlockBuilder.Direction(p.Routes.SelectMany(r=>r.Path),line.Axis)==1),"a second departure through the other turnout branch reaches the same free-line corridor in the permitted direction");
        LineSignalGroups.Put(line,LineSignalGroup.ADepartures,new[]{exitA.Id,exitA2.Id});
        var restored=JsonConvert.DeserializeObject<LineTrackDefinition>(JsonConvert.SerializeObject(line));
        Check(LineSignalGroups.Get(restored,LineSignalGroup.ADepartures).SequenceEqual(new[]{exitA.Id,exitA2.Id})&&LineSignalGroups.Get(restored,LineSignalGroup.AArrivals).SequenceEqual(new[]{entryA.Id}),"saving and restoring the draft retains all signals and the separate entry role");
        Check(forward[0].Routes.SelectMany(r=>r.Switches).Any(s=>s.Node=="wa"),"the setup proposal retains real turnout traversals even before their GFM has been enabled");
        var backward=entryB.Clone();backward.FacingReverse=true;
        Check(Reject(()=>LineSetupSearch.Find(graph,new[]{entryA,exitA,backward,exitB},exitA,backward)),"a wrongly facing neighbour entry is rejected without changing its direction or manufacturing a track path");
        var shape=LineSetupSearch.NetworkShape(graph);graph.Cuts.Add(new PlanCut{Boundary=Id(),Segment="line",Meters=400,BoundaryKind=1});
        Check(LineSetupSearch.NetworkShape(graph)==shape,"adding GFM during the tutorial does not invalidate an unchanged physical track proposal");
        graph.Edges[1].Length=801;Check(LineSetupSearch.NetworkShape(graph)!=shape,"changing native track geometry invalidates the setup proposal");graph.Edges[1].Length=800;
        line.Topology=new string('b',64);foreach(var signal in signals)line.Anchors[signal.Id]=SignalWorldBridge.AnchorKey(signal);LineSetupWorkflow.Put(library,line);library.Validate(key);
        before=JsonConvert.SerializeObject(library);var plan=LineControlSetup.Preview(library,line,signals);
        Check(JsonConvert.SerializeObject(library)==before&&plan.Positions.Count==2&&plan.Positions.All(p=>p.CreatedTarget&&p.CreatedPermission),"missing target and permission fields for both neighbours are staged together without modifying the saved diagrams");
        Check(plan.Library.Desks[1].Panel.At(5,2).LinkedAuxiliary==plan.Library.Desks[1].Panel.At(7,2).LinkedAuxiliary&&plan.Library.Desks[1].Panel.At(5,2).LinkedAuxiliary==plan.Positions.Single(p=>p.Desk==a.Id).Target&&plan.Library.Desks[2].Panel.At(5,2).LinkedAuxiliary==plan.Positions.Single(p=>p.Desk==b.Id).Target,"tutorial control setup links every selected departure at both neighbours to its generated destination");
        var oriented=library.Clone();oriented.Desks[1].Panel.At(2,2).MainSignalDirection=1;oriented.Desks[1].Panel.At(2,2).Mirror=true;oriented.Desks[2].Panel.At(2,2).Rotation=2;
        var orientedPlan=LineControlSetup.Preview(oriented,line,signals);
        Check(orientedPlan.Positions.All(p=>orientedPlan.Library.Desks.Single(d=>d.Id==p.Desk).Panel.At(p.TargetX,p.TargetY).Rotation==(p.Desk==a.Id?3:0))&&orientedPlan.Library.Desks[1].Panel.Tiles.First(t=>t.Target!=null).Mirror,"generated destination symbols take the opposite of the local entry's displayed direction, including explicit head orientation and mirror side");
        var conflict=library.Clone();var otherTarget=new AuxiliaryTarget{Function=AuxiliaryFunction.LinePermission,PermissionLine=line.Id};conflict.Desks[1].Panel.Put(new PanelTile{X=10,Y=5,Kind=PanelTileKind.AuxiliaryTarget,Target=otherTarget});conflict.Desks[1].Panel.At(7,2).LinkedAuxiliary=otherTarget.Id;string conflictBefore=JsonConvert.SerializeObject(conflict);
        Check(Reject(()=>LineControlSetup.Preview(conflict,line,signals))&&JsonConvert.SerializeObject(conflict)==conflictBefore,"a conflicting existing departure destination is explained without overwriting the saved assignment");
        var terminal=new PanelTile{Kind=PanelTileKind.LinePermission,InlinePermission=true,Ports=1};PanelConnections.Validate(terminal);
        Check(PanelConnections.Ports(terminal)==1,"permission controls can occupy a schematic track end without inventing a second rail connection");
        Check(!plan.Library.FreeLines.Single().Enabled&&!plan.Library.Automation.BlockEnabled,"preparing tutorial controls cannot enable permission or block protection before final checks");
        var bindings=LineTargetBindings.Index(plan.Library);var targetA=plan.Library.Desks[1].Panel.Tiles.Single(t=>t.Target!=null).Target;var targetB=plan.Library.Desks[2].Panel.Tiles.Single(t=>t.Target!=null).Target;
        Check(targetA.ReferenceSignal==entryA.Id&&targetA.Reverse!=entryA.FacingReverse&&targetA.PermissionLine==line.Id&&bindings[targetA.Id].Arrival==entryB.Id&&bindings[targetA.Id].Direction==1,"the A destination is derived from A entry, linked to A permission and resolves to B entry");
        Check(targetB.ReferenceSignal==entryB.Id&&bindings[targetB.Id].Arrival==entryA.Id&&bindings[targetB.Id].Direction==-1,"the B destination is derived from B entry and resolves to A through the same shared permission");
        Check(plan.Positions.All(p=>plan.Library.Desks.Single(d=>d.Id==p.Desk).Panel.At(p.PermissionX,p.PermissionY).PermissionAuxiliary==p.Target),"each generated permission field explicitly links its corresponding route destination");
        var repeated=LineControlSetup.Preview(plan.Library,line,signals);
        Check(repeated.Positions.All(p=>!p.CreatedPermission&&!p.CreatedTarget)&&repeated.Library.Desks.Sum(d=>d.Panel.Tiles.Count)==plan.Library.Desks.Sum(d=>d.Panel.Tiles.Count),"repeating the controls step reuses existing compatible target and permission fields instead of duplicating them");
        var fromField=library.Clone();fromField.Desks[1].Panel.Put(new PanelTile{X=9,Y=5,Kind=PanelTileKind.LinePermission});var selectedField=LineIndicatorTarget.Capture(fromField,a.Id,9,5);
        var fieldPreview=fromField.Clone();LineSetupWorkflow.Put(fieldPreview,line,selectedField);var positioned=LineControlSetup.Preview(fieldPreview,line,signals);
        Check(positioned.Positions.Single(p=>p.Desk==a.Id).PermissionX==9&&positioned.Positions.Single(p=>p.Desk==a.Id).PermissionY==5&&!positioned.Positions.Single(p=>p.Desk==a.Id).CreatedPermission&&fromField.Desks[1].Panel.At(9,5).Reference=="","starting tutorial setup from an unassigned permission field reuses that exact position without changing the saved field during preview");
        var bad=library.Clone();bad.Desks[1].Panel.Tiles.RemoveAll(t=>t.Reference==entryA.Id);
        Check(Reject(()=>LineControlSetup.Preview(bad,line,signals)),"a missing local entry reference produces a prerequisite instruction instead of inventing a target anchor");
        var full=library.Clone();var doc=full.Desks[1].Panel;doc.Tiles.Clear();
        for(int y=0;y<doc.Rows;y++)for(int x=0;x<doc.Columns;x++)doc.Tiles.Add(new PanelTile{X=x,Y=y,Kind=PanelTileKind.Straight,Ports=17});doc.Tiles.RemoveAll(t=>t.X==2&&t.Y==2||t.X==5&&t.Y==2);doc.Put(a.Panel.At(2,2));doc.Put(a.Panel.At(5,2));
        Check(Reject(()=>LineControlSetup.Preview(full,line,signals)),"full drawings request free space rather than overwriting track or unrelated fields");
        var enabled=line.Clone();enabled.Enabled=true;var authority=new LineDirectionAuthority{BlockEnabled=true,Occupancy=_=>TrackOccupancy.Clear};authority.Configure(new[]{enabled},_=>null);for(int i=0;i<3;i++)authority.Observe(Array.Empty<RouteRun>(),i);
        var protectedRoute=new RouteDefinition{Entry=exitB.Id,Exit=entryA.Id,Path=line.Reverse.Select(p=>p.Clone()).ToList()};
        Check(Reject(()=>authority.Reserve(new[]{protectedRoute})),"geometry preview and generated controls do not bypass the existing opposite-permission departure rejection");
    }
}
